do $do$
declare run_id bigint; rid bigint; a bigint; b bigint; r record; k int; isnew boolean;
begin
insert into public.companies(ticker,name,segment,size_tier,is_seed,is_hero) values ($q$UBER$q$,$q$Uber Technologies$q$,$q$consumer$q$,$q$large$q$,true,true),($q$AAPL$q$,$q$Apple$q$,$q$consumer$q$,$q$large$q$,true,false),($q$META$q$,$q$Meta Platforms$q$,$q$consumer$q$,$q$large$q$,true,false),($q$MSFT$q$,$q$Microsoft$q$,$q$business$q$,$q$large$q$,true,false),($q$PLTR$q$,$q$Palantir Technologies$q$,$q$business$q$,$q$large$q$,true,false),($q$NVDA$q$,$q$NVIDIA$q$,$q$infrastructure$q$,$q$large$q$,true,false),($q$TSM$q$,$q$Taiwan Semiconductor Manufacturing$q$,$q$infrastructure$q$,$q$large$q$,true,false),($q$AMD$q$,$q$Advanced Micro Devices$q$,$q$infrastructure$q$,$q$large$q$,true,false),($q$DASH$q$,$q$DoorDash$q$,$q$consumer$q$,$q$mid$q$,true,false),($q$NET$q$,$q$Cloudflare$q$,$q$business$q$,$q$mid$q$,true,false),($q$CRWV$q$,$q$CoreWeave$q$,$q$infrastructure$q$,$q$mid$q$,true,true),($q$CBRS$q$,$q$Cerebras Systems$q$,$q$infrastructure$q$,$q$mid$q$,true,false),($q$NBIS$q$,$q$Nebius Group$q$,$q$infrastructure$q$,$q$mid$q$,true,false),($q$LYFT$q$,$q$Lyft$q$,$q$consumer$q$,$q$small$q$,true,true),($q$APLD$q$,$q$Applied Digital$q$,$q$infrastructure$q$,$q$small$q$,true,false),($q$AMZN$q$,$q$Amazon$q$,$q$consumer$q$,$q$large$q$,true,false),($q$GOOGL$q$,$q$Alphabet$q$,$q$consumer$q$,$q$large$q$,true,false),($q$TSLA$q$,$q$Tesla$q$,$q$consumer$q$,$q$large$q$,true,false),($q$ORCL$q$,$q$Oracle$q$,$q$business$q$,$q$large$q$,true,false),($q$INTC$q$,$q$Intel$q$,$q$infrastructure$q$,$q$large$q$,true,false),($q$LCID$q$,$q$Lucid$q$,$q$consumer$q$,$q$small$q$,true,false),($q$LIME$q$,$q$Lime$q$,$q$consumer$q$,$q$small$q$,true,false),($q$CART$q$,$q$Instacart$q$,$q$consumer$q$,$q$mid$q$,true,false),($q$GRAB$q$,$q$Grab$q$,$q$consumer$q$,$q$mid$q$,true,false),($q$AUR$q$,$q$Aurora$q$,$q$business$q$,$q$small$q$,true,false) on conflict (ticker) do update set is_seed=true, segment=excluded.segment, size_tier=excluded.size_tier, is_hero=excluded.is_hero;
insert into public.companies(name,entity_type) select v.n,v.t from (values ($q$Fujitsu$q$,$q$public_company$q$),($q$HD Hyundai$q$,$q$public_company$q$),($q$U.S. Army$q$,$q$institution$q$)) v(n,t) where not exists (select 1 from public.companies c where lower(c.name)=lower(v.n));
create temp table _q(i int primary key, t text) on commit drop;
insert into _q values (1,$q$AWS, Microsoft Azure, and other third parties have no obligation to renew their agreements with us on commercially reasonable terms, or at all.$q$),(2,$q$For example, in March 2024, we were selected by the U.S. Army to develop and deliver the Tactical Intelligence Targeting Access Node ground station system, the Army’s first AI-defined vehicle, which involves coordination with third parties such as hardware manufacturers.$q$),(3,$q$For example, we, through Palantir Technologies Japan KK, entered into a strategic global partnership with Fujitsu Limited through which the parties will incorporate the capabilities of Foundry and AIP as a key element in the data infrastructure for Fujitsu Uvance, a portfolio of global solutions that address business challenges and solve societal issues.$q$),(4,$q$We also created a jointly-owned entity in South Korea with HD Hyundai Co. Ltd. in December 2022 in which we have a controlling interest.$q$),(5,$q$We depend on computing infrastructure operated by Amazon Web Services (“AWS”), Microsoft, and other third parties to support some of our customers and any errors, disruption, performance problems, or failure in their or our operational infrastructure could adversely affect our business, financial condition, and results of operations.$q$);
create temp table _e(n int, ty text, s text, g text, qs int[], sec text[], pct numeric, qual text, basis text, note text) on commit drop;
insert into _e values (1,$q$partners$q$,$q$PLTR$q$,$q$Fujitsu$q$,$q${3}$q$::int[],$q${business}$q$::text[],null,null,null,null),(2,$q$partners$q$,$q$PLTR$q$,$q$HD Hyundai$q$,$q${4}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(3,$q$sells_to$q$,$q$PLTR$q$,$q$U.S. Army$q$,$q${2}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(4,$q$supplies$q$,$q$Microsoft$q$,$q$PLTR$q$,$q${5,1}$q$::int[],$q${notes,mdna}$q$::text[],null,null,null,null);
create or replace function pg_temp.nid(l text) returns bigint language sql as $f$ select id from public.companies where case l when $q$Uber$q$ then ticker=$q$UBER$q$ when $q$Alphabet$q$ then ticker=$q$GOOGL$q$ when $q$Microsoft$q$ then ticker=$q$MSFT$q$ when $q$NVIDIA$q$ then ticker=$q$NVDA$q$ when $q$Tesla$q$ then ticker=$q$TSLA$q$ when $q$PLTR$q$ then ticker=$q$PLTR$q$ else lower(name)=lower(l) end order by id limit 1 $f$;
insert into public.agent_runs(agent_name,mode,target,model,cost_usd,status,review_status) values ('filings_extraction','batch',$q$PLTR 10-K M6 (staged)$q$,'claude-sonnet-5-5 via Claude Code session',0.7716,'completed','unreviewed') returning id into run_id;
for r in select * from _e order by n loop a := pg_temp.nid(r.s); b := pg_temp.nid(r.g); if r.ty in ('competes','partners') and a > b then rid := a; a := b; b := rid; end if; isnew := false; rid := null; select id into rid from public.relationships where source_id=a and target_id=b and relationship_type=r.ty order by id limit 1; if rid is null then insert into public.relationships(source_id,target_id,relationship_type,exposure_pct,exposure_qualifier,exposure_basis,exposure_as_of,source_type,status,run_id,as_of_date,note) values (a,b,r.ty,r.pct,r.qual,case when r.pct is null then 'none' else r.basis end,case when r.pct is null then null else '2025-12-31'::date end,'sec_filing','staged',run_id,'2025-12-31',r.note) returning id into rid; isnew := true; end if; if isnew then for k in 1..array_length(r.qs,1) loop insert into public.evidence(relationship_id,document_url,section,quote,quote_found,published_at) select rid,$q$https://www.sec.gov/Archives/edgar/data/1321655/000132165526000011/pltr-20251231.htm$q$,r.sec[k],t,true,$q$2026-02-17$q$ from _q where i=r.qs[k]; end loop; end if; end loop;
end $do$;
